import { AnimatedIconFrame, type AnimatedIconProps } from "../icon-frame";
import "./close.css";

export function AnimatedCloseIcon(props: AnimatedIconProps) {
  return (
    <AnimatedIconFrame name="close" {...props}>
      <g data-part="cross">
        <path d="M18 6L6 18" />
        <path d="M18 18L6 6" />
      </g>
    </AnimatedIconFrame>
  );
}

:is([data-icon-hover] .animated-icon, .animated-icon[data-icon-hover], .animated-icon[data-play]) {
  &[data-icon="close"] [data-part="cross"] {
    --icon-turn: -90deg;
    --icon-scale: 0.8;
    animation-name: icon-turn;
    animation-duration: var(--icon-duration-short);
    animation-timing-function: var(--ease-icon);
  }
}
